    },
    {
      "card_ids": ["C07"],
      "claim": "DAA1106, a high-transfer analogue with an anilide and aromatic heterocycle motif, showed rapid and high brain uptake in mice (2.1–3.5% ID/g), supporting that this structural class can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
